72	                {autoRank
73	                  ? "Resumes are automatically scored after upload. Credits are used immediately."
74	                  : "Resumes stay as Pending after upload. You choose when to rank and spend credits."}
75	              </CardDescription>
76	            </CardHeader>
77	          </Card>
78	
