import { useState } from "react";
import { useQuery } from "@tanstack/react-query";
import {
  BarChart,
  Bar,
  LineChart,
  Line,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  ResponsiveContainer,
  Cell,
} from "recharts";
import {
  Briefcase,
  Users,
  Clock,
  TrendingUp,
  Loader2,
  AlertCircle,
  ChevronDown,
} from "lucide-react";
import SidebarLayout from "@/components/SidebarLayout";
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from "@/components/ui/card";
import { Skeleton } from "@/components/ui/skeleton";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "@/hooks/useAuth";

// ─── Types ────────────────────────────────────────────────────────────────────

interface JobRow {
  id: string;
  title: string | null;
  status: string | null;
  created_at: string;
  resume_count: number;
  avg_score: number | null;
}

interface ReportsData {
  totalJobs: number;
  activeCandidates: number;
  avgScore: number;
  avgTimeToHireHours: number;
  funnelData: { stage: string; count: number }[];
  trendData: { month: string; avgHours: number }[];
  sourceData: { source: string; count: number }[];
  topJobs: JobRow[];
}

const RANGE_OPTIONS = ["Last 30 days", "Last 90 days", "Last 6 months", "All time"] as const;
type RangeOption = (typeof RANGE_OPTIONS)[number];

function rangeToDate(range: RangeOption): Date | null {
  const now = new Date();
  if (range === "Last 30 days") {
    return new Date(now.getTime() - 30 * 24 * 60 * 60 * 1000);
  }
  if (range === "Last 90 days") {
    return new Date(now.getTime() - 90 * 24 * 60 * 60 * 1000);
  }
  if (range === "Last 6 months") {
    return new Date(now.getTime() - 180 * 24 * 60 * 60 * 1000);
  }
  return null;
}

// ─── Stat card ────────────────────────────────────────────────────────────────

interface StatCardProps {
  title: string;
  value: string;
  sub?: string;
  icon: React.ReactNode;
  loading?: boolean;
}

function StatCard({ title, value, sub, icon, loading }: StatCardProps) {
  if (loading) {
    return (
      <Card className="border border-border/60 shadow-sm">
        <CardContent className="pt-5 pb-4 px-5">
          <Skeleton className="h-4 w-28 mb-3" />
          <Skeleton className="h-8 w-20 mb-1.5" />
          <Skeleton className="h-3 w-24" />
        </CardContent>
      </Card>
    );
  }
  return (
    <Card className="border border-border/60 shadow-sm">
      <CardContent className="pt-5 pb-4 px-5">
        <div className="flex items-start justify-between mb-2">
          <p className="text-xs font-medium text-muted-foreground">{title}</p>
          <span className="text-muted-foreground/60">{icon}</span>
        </div>
        <p className="text-2xl font-bold text-foreground leading-none">{value}</p>
        {sub && <p className="text-xs text-muted-foreground mt-1.5">{sub}</p>}
      </CardContent>
    </Card>
  );
}

// ─── Chart skeletons ──────────────────────────────────────────────────────────

function ChartSkeleton({ height = 220 }: { height?: number }) {
  return (
    <div className="space-y-2">
      <Skeleton className="h-4 w-36" />
      <Skeleton style={{ height }} className="w-full rounded-lg" />
    </div>
  );
}

// ─── Main page ────────────────────────────────────────────────────────────────

const Reports = () => {
  const { user } = useAuth();
  const [range, setRange] = useState<RangeOption>("Last 30 days");

  const { data, isLoading, error } = useQuery<ReportsData>({
    queryKey: ["reports", user?.id, range],
    enabled: !!user,
    queryFn: async (): Promise<ReportsData> => {
      const since = rangeToDate(range);

      // ── 1. Jobs in range ──
      let jobsQ = (supabase as any)
        .from("jobs")
        .select("id, title, status, created_at")
        .eq("user_id", user!.id)
        .order("created_at", { ascending: false });

      if (since) {
        jobsQ = jobsQ.gte("created_at", since.toISOString());
      }

      const { data: jobs, error: jobsErr } = await jobsQ;
      if (jobsErr) throw new Error(jobsErr.message);

      const jobIds: string[] = (jobs ?? []).map((j: any) => j.id);

      // ── 2. Resumes for those jobs ──
      let resumes: any[] = [];
      if (jobIds.length > 0) {
        const { data: rData, error: rErr } = await (supabase as any)
          .from("resumes")
          .select("id, job_id, status, created_at")
          .in("job_id", jobIds);
        if (rErr) throw new Error(rErr.message);
        resumes = rData ?? [];
      }

      // ── 3. Results for scores ──
      let results: any[] = [];
      if (resumes.length > 0) {
        const resumeIds = resumes.map((r: any) => r.id);
        const { data: rData, error: rErr } = await (supabase as any)
          .from("results")
          .select("resume_id, job_id, overall_score")
          .in("resume_id", resumeIds);
        if (rErr) throw new Error(rErr.message);
        results = rData ?? [];
      }

      // ── Derived stats ──
      const totalJobs = (jobs ?? []).length;
      const activeCandidates = resumes.filter((r: any) => r.status !== "failed").length;
      const scores = results.map((r: any) => r.overall_score as number).filter(Boolean);
      const avgScore = scores.length > 0 ? scores.reduce((a: number, b: number) => a + b, 0) / scores.length : 0;

      // Avg time to hire: time between job created_at and last resume done status
      // Approximate with avg time between job creation and last resume processed
      let totalHours = 0;
      let jobsWithResumes = 0;
      for (const job of jobs ?? []) {
        const jobResumes = resumes.filter((r: any) => r.job_id === job.id && r.status === "done");
        if (jobResumes.length > 0) {
          const latest = jobResumes.reduce((max: any, r: any) =>
            new Date(r.created_at) > new Date(max.created_at) ? r : max
          );
          const diffMs = new Date(latest.created_at).getTime() - new Date(job.created_at).getTime();
          totalHours += diffMs / (1000 * 60 * 60);
          jobsWithResumes++;
        }
      }
      const avgTimeToHireHours = jobsWithResumes > 0 ? totalHours / jobsWithResumes : 0;

      // ── Funnel data ──
      const pending = resumes.filter((r: any) => r.status === "pending").length;
      const processing = resumes.filter((r: any) => r.status === "processing").length;
      const done = resumes.filter((r: any) => r.status === "done").length;
      const failed = resumes.filter((r: any) => r.status === "failed").length;

      const funnelData = [
        { stage: "Received", count: resumes.length },
        { stage: "Pending", count: pending },
        { stage: "Processing", count: processing },
        { stage: "Scored", count: done },
        { stage: "Failed", count: failed },
      ];

      // ── Trend: group by month (last 6 months) ──
      const monthMap: Record<string, { totalHours: number; count: number }> = {};
      for (const job of jobs ?? []) {
        const jobResumes = resumes.filter((r: any) => r.job_id === job.id && r.status === "done");
        if (jobResumes.length === 0) continue;
        const latest = jobResumes.reduce((max: any, r: any) =>
          new Date(r.created_at) > new Date(max.created_at) ? r : max
        );
        const diffHours = (new Date(latest.created_at).getTime() - new Date(job.created_at).getTime()) / (1000 * 60 * 60);
        const monthKey = new Date(job.created_at).toLocaleString("default", { month: "short", year: "2-digit" });
        if (!monthMap[monthKey]) monthMap[monthKey] = { totalHours: 0, count: 0 };
        monthMap[monthKey].totalHours += diffHours;
        monthMap[monthKey].count++;
      }

      const trendData = Object.entries(monthMap).map(([month, v]) => ({
        month,
        avgHours: Math.round(v.totalHours / v.count),
      }));

      // ── Source breakdown (by job status as a proxy) ──
      const statusCounts: Record<string, number> = {};
      for (const j of jobs ?? []) {
        const s = j.status ?? "unknown";
        statusCounts[s] = (statusCounts[s] ?? 0) + 1;
      }
      const sourceData = Object.entries(statusCounts).map(([source, count]) => ({ source, count }));

      // ── Top jobs by avg score ──
      const topJobs: JobRow[] = (jobs ?? [])
        .map((j: any) => {
          const jobResults = results.filter((r: any) => r.job_id === j.id);
          const jobScores = jobResults.map((r: any) => r.overall_score as number).filter(Boolean);
          const avgJobScore = jobScores.length > 0
            ? jobScores.reduce((a: number, b: number) => a + b, 0) / jobScores.length
            : null;
          return {
            id: j.id,
            title: j.title,
            status: j.status,
            created_at: j.created_at,
            resume_count: resumes.filter((r: any) => r.job_id === j.id).length,
            avg_score: avgJobScore ? Math.round(avgJobScore) : null,
          } as JobRow;
        })
        .sort((a: JobRow, b: JobRow) => (b.avg_score ?? 0) - (a.avg_score ?? 0))
        .slice(0, 10);

      return {
        totalJobs,
        activeCandidates,
        avgScore: Math.round(avgScore),
        avgTimeToHireHours: Math.round(avgTimeToHireHours * 10) / 10,
        funnelData,
        trendData,
        sourceData,
        topJobs,
      };
    },
  });

  const funnelColors = ["#6366f1", "#8b5cf6", "#a78bfa", "#c4b5fd", "#ef4444"];

  return (
    <SidebarLayout>
      <main className="w-full max-w-5xl mx-auto px-4 sm:px-6 lg:px-8 py-8">
        {/* Header */}
        <div className="flex items-start justify-between mb-6">
          <div>
            <h1 className="text-2xl font-bold text-foreground mb-0.5">Reports</h1>
            <p className="text-sm text-muted-foreground">Hiring analytics for your account.</p>
          </div>

          {/* Range filter */}
          <DropdownMenu>
            <DropdownMenuTrigger asChild>
              <Button variant="outline" size="sm" className="gap-1.5 text-xs h-8">
                {range}
                <ChevronDown className="h-3.5 w-3.5 text-muted-foreground" />
              </Button>
            </DropdownMenuTrigger>
            <DropdownMenuContent align="end" className="text-sm">
              {RANGE_OPTIONS.map((opt) => (
                <DropdownMenuItem key={opt} onClick={() => setRange(opt)} className="text-xs">
                  {opt}
                </DropdownMenuItem>
              ))}
            </DropdownMenuContent>
          </DropdownMenu>
        </div>

        {/* Error state */}
        {error && (
          <Card className="border-destructive/40 mb-6">
            <CardContent className="py-8 flex flex-col items-center gap-2 text-center">
              <AlertCircle className="h-7 w-7 text-destructive" />
              <p className="text-sm text-muted-foreground">Failed to load report data. Please refresh.</p>
            </CardContent>
          </Card>
        )}

        {/* ── Stat cards ── */}
        <div className="grid grid-cols-2 sm:grid-cols-4 gap-3 mb-6">
          <StatCard
            title="Total Jobs"
            value={isLoading ? "—" : String(data?.totalJobs ?? 0)}
            sub="In selected period"
            icon={<Briefcase className="h-4 w-4" />}
            loading={isLoading}
          />
          <StatCard
            title="Active Candidates"
            value={isLoading ? "—" : String(data?.activeCandidates ?? 0)}
            sub="Resumes uploaded"
            icon={<Users className="h-4 w-4" />}
            loading={isLoading}
          />
          <StatCard
            title="Avg Time-to-Hire"
            value={isLoading ? "—" : `${data?.avgTimeToHireHours ?? 0}h`}
            sub="From job to scored"
            icon={<Clock className="h-4 w-4" />}
            loading={isLoading}
          />
          <StatCard
            title="Avg Score"
            value={isLoading ? "—" : `${data?.avgScore ?? 0}%`}
            sub="Across all candidates"
            icon={<TrendingUp className="h-4 w-4" />}
            loading={isLoading}
          />
        </div>

        {/* ── Charts row ── */}
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mb-6">
          {/* Hiring funnel */}
          <Card className="border border-border/60 shadow-sm">
            <CardHeader className="pb-2 px-5 pt-4">
              <CardTitle className="text-sm font-semibold">Hiring Funnel</CardTitle>
              <CardDescription className="text-xs">Candidates by pipeline stage</CardDescription>
            </CardHeader>
            <CardContent className="px-4 pb-4">
              {isLoading ? (
                <ChartSkeleton height={200} />
              ) : (
                <ResponsiveContainer width="100%" height={200}>
                  <BarChart data={data?.funnelData ?? []} margin={{ top: 4, right: 8, left: -20, bottom: 0 }}>
                    <CartesianGrid strokeDasharray="3 3" stroke="hsl(var(--border))" vertical={false} />
                    <XAxis
                      dataKey="stage"
                      tick={{ fontSize: 11, fill: "hsl(var(--muted-foreground))" }}
                      axisLine={false}
                      tickLine={false}
                    />
                    <YAxis
                      tick={{ fontSize: 11, fill: "hsl(var(--muted-foreground))" }}
                      axisLine={false}
                      tickLine={false}
                    />
                    <Tooltip
                      contentStyle={{
                        backgroundColor: "hsl(var(--popover))",
                        border: "1px solid hsl(var(--border))",
                        borderRadius: 8,
                        fontSize: 12,
                      }}
                      cursor={{ fill: "hsl(var(--muted))" }}
                    />
                    <Bar dataKey="count" radius={[4, 4, 0, 0]}>
                      {(data?.funnelData ?? []).map((_: unknown, idx: number) => (
                        <Cell key={idx} fill={funnelColors[idx % funnelColors.length]} />
                      ))}
                    </Bar>
                  </BarChart>
                </ResponsiveContainer>
              )}
            </CardContent>
          </Card>

          {/* Time-to-hire trend */}
          <Card className="border border-border/60 shadow-sm">
            <CardHeader className="pb-2 px-5 pt-4">
              <CardTitle className="text-sm font-semibold">Time-to-Hire Trend</CardTitle>
              <CardDescription className="text-xs">Avg hours per month</CardDescription>
            </CardHeader>
            <CardContent className="px-4 pb-4">
              {isLoading ? (
                <ChartSkeleton height={200} />
              ) : (data?.trendData ?? []).length === 0 ? (
                <div className="flex flex-col items-center justify-center h-[200px] text-center gap-2">
                  <Clock className="h-7 w-7 text-muted-foreground/40" />
                  <p className="text-xs text-muted-foreground">Not enough data yet</p>
                </div>
              ) : (
                <ResponsiveContainer width="100%" height={200}>
                  <LineChart data={data?.trendData ?? []} margin={{ top: 4, right: 8, left: -20, bottom: 0 }}>
                    <CartesianGrid strokeDasharray="3 3" stroke="hsl(var(--border))" vertical={false} />
                    <XAxis
                      dataKey="month"
                      tick={{ fontSize: 11, fill: "hsl(var(--muted-foreground))" }}
                      axisLine={false}
                      tickLine={false}
                    />
                    <YAxis
                      tick={{ fontSize: 11, fill: "hsl(var(--muted-foreground))" }}
                      axisLine={false}
                      tickLine={false}
                    />
                    <Tooltip
                      contentStyle={{
                        backgroundColor: "hsl(var(--popover))",
                        border: "1px solid hsl(var(--border))",
                        borderRadius: 8,
                        fontSize: 12,
                      }}
                    />
                    <Line
                      type="monotone"
                      dataKey="avgHours"
                      stroke="#6366f1"
                      strokeWidth={2}
                      dot={{ r: 3, fill: "#6366f1" }}
                      activeDot={{ r: 5 }}
                    />
                  </LineChart>
                </ResponsiveContainer>
              )}
            </CardContent>
          </Card>
        </div>

        {/* ── Source breakdown ── */}
        <Card className="border border-border/60 shadow-sm mb-6">
          <CardHeader className="pb-2 px-5 pt-4">
            <CardTitle className="text-sm font-semibold">Job Status Breakdown</CardTitle>
            <CardDescription className="text-xs">Count of jobs by their current status</CardDescription>
          </CardHeader>
          <CardContent className="px-4 pb-4">
            {isLoading ? (
              <ChartSkeleton height={160} />
            ) : (data?.sourceData ?? []).length === 0 ? (
              <div className="flex flex-col items-center justify-center h-[160px] text-center gap-2">
                <Briefcase className="h-7 w-7 text-muted-foreground/40" />
                <p className="text-xs text-muted-foreground">No job data in this period</p>
              </div>
            ) : (
              <ResponsiveContainer width="100%" height={160}>
                <BarChart
                  data={data?.sourceData ?? []}
                  layout="vertical"
                  margin={{ top: 0, right: 20, left: 10, bottom: 0 }}
                >
                  <CartesianGrid strokeDasharray="3 3" stroke="hsl(var(--border))" horizontal={false} />
                  <XAxis
                    type="number"
                    tick={{ fontSize: 11, fill: "hsl(var(--muted-foreground))" }}
                    axisLine={false}
                    tickLine={false}
                  />
                  <YAxis
                    type="category"
                    dataKey="source"
                    tick={{ fontSize: 11, fill: "hsl(var(--muted-foreground))" }}
                    axisLine={false}
                    tickLine={false}
                    width={80}
                  />
                  <Tooltip
                    contentStyle={{
                      backgroundColor: "hsl(var(--popover))",
                      border: "1px solid hsl(var(--border))",
                      borderRadius: 8,
                      fontSize: 12,
                    }}
                    cursor={{ fill: "hsl(var(--muted))" }}
                  />
                  <Bar dataKey="count" fill="#6366f1" radius={[0, 4, 4, 0]} />
                </BarChart>
              </ResponsiveContainer>
            )}
          </CardContent>
        </Card>

        {/* ── Top jobs table ── */}
        <Card className="border border-border/60 shadow-sm">
          <CardHeader className="px-5 pt-4 pb-2">
            <CardTitle className="text-sm font-semibold">Top Jobs by Score</CardTitle>
            <CardDescription className="text-xs">Your highest-performing job postings</CardDescription>
          </CardHeader>
          <CardContent className="p-0">
            {isLoading ? (
              <div className="p-5 space-y-3">
                {[1, 2, 3, 4].map((i) => (
                  <div key={i} className="flex items-center gap-3">
                    <Skeleton className="h-4 flex-1" />
                    <Skeleton className="h-4 w-16" />
                    <Skeleton className="h-4 w-12" />
                    <Skeleton className="h-4 w-10" />
                  </div>
                ))}
              </div>
            ) : (data?.topJobs ?? []).length === 0 ? (
              <div className="flex flex-col items-center justify-center py-12 text-center gap-2">
                <Briefcase className="h-7 w-7 text-muted-foreground/40" />
                <p className="text-xs text-muted-foreground">No jobs in this period</p>
              </div>
            ) : (
              <Table>
                <TableHeader>
                  <TableRow>
                    <TableHead className="text-xs pl-5">Job Title</TableHead>
                    <TableHead className="text-xs">Status</TableHead>
                    <TableHead className="text-xs">Candidates</TableHead>
                    <TableHead className="text-xs">Avg Score</TableHead>
                    <TableHead className="text-xs pr-5">Created</TableHead>
                  </TableRow>
